def completar_contexto_reservas(apps, schema_editor):
    Reserva = apps.get_model('webcitt', 'Reserva')
    Registro = apps.get_model('webcitt', 'RegistroParticipanteReserva')
    UserProfile = apps.get_model('webcitt', 'UserProfile')
    User = apps.get_model(*settings.AUTH_USER_MODEL.split('.'))
    mapping = {
        'Docencia': ('docencia_practica', 'practica_curricular'),
        'Investigación': ('investigacion_innovacion', 'proyecto_investigacion'),
        'Vinculación': ('vinculacion', 'proyecto_vinculacion'),
        'Capacitación': ('capacitacion', 'curso'),
        'Servicios': ('servicio_cientifico_tecnologico', 'servicio_autorizado'),
        'Proyecto de Titulación': ('titulacion', 'trabajo_titulacion'),
        'Otro': ('otro', 'otro'),
    }
    perfiles = {perfil.user_id: perfil for perfil in UserProfile.objects.all()}
    for reserva in Reserva.objects.all().iterator():
        codigo, subtipo = mapping.get(reserva.proposito, ('otro', 'otro'))
        reserva.proposito_codigo = codigo
        reserva.subtipo_actividad = subtipo
        reserva.alcance_beneficiario = 'perfil_solicitante'
        reserva.facultad_beneficiaria = reserva.facultad_solicitante or ''
        reserva.carrera_beneficiaria = reserva.carrera_solicitante or ''
        reserva.entidad_beneficiaria = reserva.institucion or ''
        reserva.save(update_fields=[
            'proposito_codigo', 'subtipo_actividad', 'alcance_beneficiario',
            'facultad_beneficiaria', 'carrera_beneficiaria',
            'entidad_beneficiaria',
        ])

        usuarios = []
        if reserva.usuario_id:
            usuarios.append((reserva.usuario_id, 'solicitante'))
        usuarios.extend(
            (usuario_id, 'participante')
            for usuario_id in reserva.participantes.values_list('id', flat=True)
        )
        for usuario_id, rol in usuarios:
            usuario = reserva.usuario if usuario_id == reserva.usuario_id else None
            if usuario is None:
                usuario = User.objects.filter(pk=usuario_id).first()
            if usuario is None:
                continue
            perfil = perfiles.get(usuario_id)
            nombre = ' '.join(filter(None, [
                getattr(usuario, 'first_name', ''),
                getattr(usuario, 'last_name', ''),
            ])).strip() or usuario.username
            Registro.objects.get_or_create(
                reserva_id=reserva.pk,
                usuario_id=usuario_id,
                defaults={
                    'rol': rol,
                    'nombre': nombre,
                    'correo': usuario.email or '',
                    'tipo_usuario': getattr(perfil, 'tipo_usuario', '') or '',
                    'facultad': getattr(perfil, 'facultad', '') or '',
                    'carrera': getattr(perfil, 'carrera', '') or '',
                    'nivel_academico': getattr(perfil, 'nivel_academico', '') or '',
                    'institucion': getattr(perfil, 'institucion', '') or '',
                },
            )


